<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppHeader from '../components/AppHeader.vue'
import EquipmentShopModal from '../components/EquipmentShopModal.vue'
import { attributes } from '../data/bramble'
import { gearShopItems as legacyGearShopItems, skillDefinitions } from '../data/characterOptions'
import { attunableLores, loreSpells } from '../data/magicOptions'
import { ruleSourceDocuments } from '../data/rulesSource'
import { canonicalTalentName, talentNameMatches } from '../data/talentCategories'
import { advancementCost, equipmentAttachmentTargets } from '../rules/rulesEngine'
import { canonicalGearCostWp, economyGearCatalog, isTrinketGear, ordinaryGearResaleWp, protectiveGearKind } from '../rules/economy'
import { MAGIC_LEVEL_MAX, isSignatureSpell, magicSpellAllowance, magicSpellGainAtLevel } from '../rules/magicRules'
import { talentRequirementFromText, talentRequirementSatisfied } from '../rules/talentRequirements'
import { formatThreadpieceBalance, formatThreadpieceWp, threadpieceValueToWp, WP_PER_NP, WP_PER_SP } from '../rules/threadpieces'
import { canEquipProtectiveEquipment, characterStatus, characterWealthWp, loadCharacters, normalizeTrinketEquipment, setProtectiveEquipmentEquipped, setTrinketEquipmentEquipped, writeCharacters, type CharacterRecord, type PurchasedEquipment } from '../services/characters'
import { loadCustomData, type CustomSpellItem } from '../services/customData'

const gearShopItems=economyGearCatalog(legacyGearShopItems)
const route=useRoute(),router=useRouter()
const characters=ref<CharacterRecord[]>(loadCharacters())
const selectedCharacter=computed(()=>characters.value.find(item=>item.id===String(route.params.id||''))||null)
const character=computed(()=>selectedCharacter.value&&characterStatus(selectedCharacter.value)==='approved'&&!selectedCharacter.value.locked?selectedCharacter.value:null)
const message=ref('')
const xpAdd=ref(0),currencyAmount=ref(0),currencyUnit=ref<'wp'|'np'|'sp'|'bp'>('sp'),treasureText=ref('')
const skillName=ref(''),newSkill=ref(''),newTalent=ref('')
const newLoreAttunement=ref(''),newLoreSpell=ref(''),newInvocationSpell=ref('')
const selectedGearName=ref(''),selectedGearChoice=ref(''),shopOpen=ref(false)
const customSpells=loadCustomData().filter((item):item is CustomSpellItem=>item.type==='spell')

function commit(mutator:(draft:CharacterRecord)=>void){
  const id=String(route.params.id||''),next=loadCharacters(),draft=next.find(item=>item.id===id)
  if(!draft||characterStatus(draft)!=='approved'){message.value='Approve this character before using Level Up.';return false}
  if(draft.locked){message.value='Unlock this character before using Level Up.';return false}
  mutator(draft);draft.status='approved';draft.draft=false;draft.updatedAt=new Date().toISOString()
  const saved=writeCharacters(next);if(!saved.ok){message.value=saved.message;return false}characters.value=loadCharacters();return true
}
function xp(){return Number(character.value?.experience||0)}
function spend(cost:number,action:(draft:CharacterRecord)=>void,label:string){if(!character.value)return;if(xp()<cost){message.value=`${label} costs ${cost} XP; ${xp()} XP available.`;return}if(!commit(draft=>{draft.experience=Number(draft.experience||0)-cost;action(draft)}))return;message.value=`${label} purchased for ${cost} XP.`}
function applyRewards(){
  if(!character.value)return
  const xpValue=Math.max(0,Math.floor(Number(xpAdd.value)||0)),currencyValue=Math.max(0,Math.floor(Number(currencyAmount.value)||0)),treasure=treasureText.value.trim()
  const addedWp=currencyValue?threadpieceValueToWp(currencyValue,currencyUnit.value):0
  if(!xpValue&&!addedWp&&!treasure){message.value='Enter XP, Threadpieces, or treasure before applying rewards.';return}
  if(!commit(draft=>{if(xpValue)draft.experience=Number(draft.experience||0)+xpValue;if(addedWp){draft.currencyAddedWp=Math.max(0,Number(draft.currencyAddedWp)||0)+addedWp;draft.wealthWp=characterWealthWp(draft)+addedWp}if(treasure)draft.treasure=[...(draft.treasure||[]),treasure]}))return
  const applied=[xpValue?`${xpValue} XP`:'',addedWp?formatThreadpieceWp(addedWp):'',treasure?`treasure: ${treasure}`:''].filter(Boolean).join(' · ')
  xpAdd.value=0;currencyAmount.value=0;treasureText.value='';message.value=`Applied ${applied}.`
}
function removeTreasure(index:number){if(!commit(draft=>{draft.treasure=(draft.treasure||[]).filter((_,itemIndex)=>itemIndex!==index)}))return;message.value='Treasure removed.'}

function attributeCost(rank:number){return advancementCost('attribute',rank)}
function raiseAttribute(id:(typeof attributes)[number]['id']){const c=character.value;if(!c)return;const rank=Number(c.attributes[id]||0);spend(attributeCost(rank),draft=>{draft.attributes[id]=rank+1},`${attributes.find(a=>a.id===id)?.name} Rank ${rank+1}`)}
const skills=computed(()=>Object.entries(character.value?.skillRanks||{}).sort(([a],[b])=>a.localeCompare(b)))
const newSkillCost=advancementCost('new-skill'),talentCost=advancementCost('talent')
function skillCost(rank:number){return advancementCost('skill',rank)}
function raiseSkill(){const c=character.value;if(!c||!skillName.value)return;const current=Number(c.skillRanks?.[skillName.value]||0),selected=skillName.value;spend(skillCost(current),draft=>{draft.skillRanks={...(draft.skillRanks||{}),[selected]:current+1}},`${selected} Rank ${current+1}`)}
function addSkill(){const c=character.value;if(!c||!newSkill.value)return;if(c.skillRanks?.[newSkill.value]){message.value='That Skill is already known.';return}const selected=newSkill.value;spend(newSkillCost,draft=>{draft.skillRanks={...(draft.skillRanks||{}),[selected]:1};draft.skills=Array.from(new Set([...(draft.skills||[]),selected]))},`${selected} Rank 1`);newSkill.value=''}

const talentSections=ruleSourceDocuments.talents.sections
function talentText(name:string){const section=talentSections.find(item=>talentNameMatches(item.heading,name));return section?.blocks.filter(block=>block.type==='paragraph').map(block=>block.type==='paragraph'?block.text:'').join(' ')||''}
function talentRequires(name:string){return talentRequirementFromText(talentText(name))}
function talentKnown(name:string){return(character.value?.talents||[]).some(existing=>talentNameMatches(existing,name))}
const talentOptions=computed(()=>Array.from(new Set(talentSections.map(section=>canonicalTalentName(section.heading)).filter(name=>name&&name!=='Overview'&&name!=='TALENTS'&&!name.startsWith('KEYWORDS')))).filter(name=>!talentKnown(name)&&talentRequirementSatisfied(talentRequires(name),character.value?.talents||[],name)).sort())
function addTalent(){const c=character.value;if(!c||!newTalent.value)return;const talent=canonicalTalentName(newTalent.value),required=talentRequires(talent);if(!talentRequirementSatisfied(required,c.talents||[],talent)){message.value=required?`${talent} requires ${required}.`:'That Talent is not currently available.';return}spend(talentCost,draft=>{draft.talents=Array.from(new Set([...(draft.talents||[]),talent]))},talent);newTalent.value=''}

function levelUpIsSignature(name:string){return isSignatureSpell(name)||customSpells.some(spell=>spell.name===name&&spell.signature)}
const magicLevel=computed(()=>Number(character.value?.magicLevel??(character.value?.path==='magic'?1:0)))
const magicAllowance=computed(()=>magicSpellAllowance(magicLevel.value))
const nextMagicLevel=computed(()=>Math.min(MAGIC_LEVEL_MAX,magicLevel.value+1))
const nextMagicAllowance=computed(()=>magicSpellAllowance(nextMagicLevel.value))
const nextMagicGain=computed(()=>magicSpellGainAtLevel(nextMagicLevel.value))
const knownLoreSpells=computed(()=>Array.from(new Set((character.value?.spells||[]).filter(Boolean).filter(name=>!levelUpIsSignature(name)))))
const knownInvocationSpells=computed(()=>Array.from(new Set([...(character.value?.invocationSpells||[]),...(character.value?.invocationSpell?[character.value.invocationSpell]:[])].filter(Boolean))))
const loreClaimsRemaining=computed(()=>Math.max(0,magicAllowance.value.lore-knownLoreSpells.value.length)),invocationClaimsRemaining=computed(()=>Math.max(0,magicAllowance.value.invocation-knownInvocationSpells.value.length))
const levelUpCustomSpells=computed(()=>character.value?.allowCustomData?customSpells:[])
const loreSpellOptions=computed(()=>{const builtIn=Object.entries(loreSpells).filter(([lore])=>lore!=='Invocation').flatMap(([,names])=>names).filter(name=>!isSignatureSpell(name)),custom=levelUpCustomSpells.value.filter(spell=>spell.lore!=='Invocation'&&!spell.signature).map(spell=>spell.name),known=new Set(knownLoreSpells.value);return Array.from(new Set([...builtIn,...custom])).filter(name=>!known.has(name)).sort()})
const invocationSpellOptions=computed(()=>{const builtIn=loreSpells.Invocation||[],custom=levelUpCustomSpells.value.filter(spell=>spell.lore==='Invocation'&&!spell.signature).map(spell=>spell.name),known=new Set(knownInvocationSpells.value);return Array.from(new Set([...builtIn,...custom])).filter(name=>!known.has(name)).sort()})
const attunementOptions=computed(()=>Array.from(new Set([...attunableLores,...levelUpCustomSpells.value.filter(spell=>spell.lore!=='Invocation').map(spell=>spell.lore)])).sort())
function raiseMagic(){const c=character.value;if(!c)return;const current=magicLevel.value;if(current>=MAGIC_LEVEL_MAX){message.value='Magic Level is already at the maximum of 10.';return}const cost=advancementCost('magic',current);spend(cost,draft=>{draft.magicLevel=current+1},`Magic Level ${current+1}`)}
function claimLoreAttunement(){const lore=newLoreAttunement.value;if(!lore||!character.value||magicLevel.value<1||character.value.loreAttunement)return;if(!commit(draft=>{draft.loreAttunement=lore}))return;newLoreAttunement.value='';message.value=`Attuned to the Lore of ${lore}.`}
function claimLoreSpell(){const spell=newLoreSpell.value;if(!spell||loreClaimsRemaining.value<1)return;if(!commit(draft=>{draft.spells=Array.from(new Set([...(draft.spells||[]),spell]))}))return;newLoreSpell.value='';message.value=`Learned Lore Spell: ${spell}.`}
function claimInvocationSpell(){const spell=newInvocationSpell.value;if(!spell||invocationClaimsRemaining.value<1)return;if(!commit(draft=>{draft.invocationSpells=Array.from(new Set([...(draft.invocationSpells||[]),...(draft.invocationSpell?[draft.invocationSpell]:[]),spell]));draft.invocationSpell=undefined}))return;newInvocationSpell.value='';message.value=`Learned Invocation: ${spell}.`}

const wealthLabel=computed(()=>formatThreadpieceBalance(character.value?characterWealthWp(character.value):0))
const gearOptions=computed(()=>[...gearShopItems].sort((a,b)=>a.category.localeCompare(b.category)||a.name.localeCompare(b.name)))
const selectedGear=computed(()=>gearOptions.value.find(item=>item.name===selectedGearName.value)||null)
watch(selectedGearName,()=>{selectedGearChoice.value=''})
function gearMightRequirement(item:typeof gearShopItems[number]){if(item.category!=='Armor & Shield')return 0;return Number((item.detail.split('·')[0]||'0').replace(/[^0-9]/g,''))||0}
function gearPrice(item:typeof gearShopItems[number]){return canonicalGearCostWp(item)}
function gearPriceLabel(item:typeof gearShopItems[number]){return formatThreadpieceWp(gearPrice(item))}
function gearDisplayDetail(item:typeof gearShopItems[number]){if(item.category==='Armor & Shield'){const p=item.detail.split('·').map(part=>part.trim());if(p.length>=5)return`Might Requirement ${p[0]} · Guts Bonus ${p[1]} · Mana Syphon ${p[2]} · Armor Penalty ${p[3]} · Weight ${p[4]}`}if(item.category==='Weapon'){const p=item.detail.split('·').map(part=>part.trim());if(p.length>=2)return`Damage ${p[0]} · Weight ${p[1]}${p.length>2?` · Properties ${p.slice(2).join(' · ')}`:''}`}return item.detail}
function purchaseFromSharedShop(payload:{item:typeof gearShopItems[number];choice:string}){selectedGearName.value=payload.item.name;selectedGearChoice.value=payload.choice;purchaseGear()}
function purchaseGear(){const c=character.value,item=selectedGear.value;if(!c||!item)return;const choice=selectedGearChoice.value.trim();if(item.choices?.length&&!choice){message.value=`Choose an option for ${item.name}.`;return}const required=gearMightRequirement(item);if(Number(c.attributes.might||0)<required){message.value=`${item.name} requires Might Rank ${required}.`;return}const costWp=gearPrice(item);if(characterWealthWp(c)<costWp){message.value=`${item.name} costs ${gearPriceLabel(item)}; ${wealthLabel.value} available.`;return}const kind=protectiveGearKind(item),equipped=kind?!((c.equipment||[]).some(existing=>protectiveGearKind(existing)===kind&&existing.equipped===true)):undefined;const purchased:PurchasedEquipment={name:item.name,costWp,costPaidWp:costWp,costSp:costWp/WP_PER_SP,costNp:costWp/WP_PER_NP,category:item.category,detail:gearDisplayDetail(item),effect:item.effect,choice:choice||undefined,quantity:1,statBonuses:item.statBonuses,equipped};if(!commit(draft=>{draft.wealthWp=Math.max(0,characterWealthWp(draft)-costWp);draft.equipment=normalizeTrinketEquipment([...(draft.equipment||[]),purchased])}))return;selectedGearName.value='';selectedGearChoice.value='';message.value=`Purchased ${item.name} for ${gearPriceLabel(item)}.`}
function equipProtective(index:number){if(!commit(draft=>{draft.equipment=setProtectiveEquipmentEquipped(draft.equipment,index,true)}))return;message.value='Protective equipment updated.'}
function setOwnedAttachment(index:number,event:Event){const value=(event.target as HTMLSelectElement|null)?.value||undefined;if(!commit(draft=>{const item=draft.equipment?.[index];if(item)item.attachedTo=value}))return;message.value=value?'Attachment updated.':'Attachment cleared.'}
function ownedAttachmentTargets(item:PurchasedEquipment){return equipmentAttachmentTargets(item,character.value?.equipment)}
function toggleOwnedTrinket(index:number){const current=character.value?.equipment?.[index];if(!current)return;if(!commit(draft=>{draft.equipment=setTrinketEquipmentEquipped(draft.equipment,index,current.equipped!==true)}))return;message.value=`${current.equipped?'Unequipped':'Equipped'} ${current.name}.`}
function sellOwnedGear(index:number){const owned=character.value?.equipment?.[index];if(!owned)return;const quantity=Math.max(1,Math.floor(Number(owned.quantity)||1)),resaleWp=ordinaryGearResaleWp(owned)*quantity,kind=protectiveGearKind(owned),wasEquipped=Boolean(kind&&owned.equipped);if(!commit(draft=>{const equipment=[...(draft.equipment||[])];equipment.splice(index,1);let next=equipment;if(wasEquipped&&kind){const replacementIndex=equipment.findIndex(item=>protectiveGearKind(item)===kind);next=replacementIndex>=0?setProtectiveEquipmentEquipped(equipment,replacementIndex,true):equipment}draft.equipment=normalizeTrinketEquipment(next);draft.wealthWp=characterWealthWp(draft)+resaleWp}))return;message.value=`Sold ${owned.name} for ${formatThreadpieceWp(resaleWp)}.`}
function finish(){void router.push('/characters')}
</script>

<template>
<main class="page level-up-page"><AppHeader compact back-to="/characters" back-label="Back to Character Roster" prefer-back-to />
<template v-if="character"><div class="page-title-block level-up-title"><h1>Level Up {{ character.name }}</h1><p>Spend Experience, record rewards, and advance the same sections shown on the Character Sheet.</p></div>
<section class="level-up-rewards card-surface"><header><div><h2>Experience, Currency &amp; Treasure</h2><small>Apply all entered campaign rewards with one action.</small></div><div class="reward-balances"><strong>{{ character.experience||0 }} XP</strong><strong>{{ wealthLabel }}</strong></div></header><div class="reward-input-grid"><label>Add XP<input v-model.number="xpAdd" class="field-control" type="number" min="0" /></label><label>Threadpieces<input v-model.number="currencyAmount" class="field-control" type="number" min="0" step="1" /></label><label>Piece<select v-model="currencyUnit" class="field-control"><option value="wp">wp</option><option value="np">np</option><option value="sp">sp</option><option value="bp">bp</option></select></label><label class="reward-treasure">Treasure<input v-model="treasureText" class="field-control" type="text" placeholder="Treasure name or short description" /></label></div><button class="primary-button wide" type="button" @click="applyRewards">Apply Rewards</button><div v-if="character.treasure?.length" class="treasure-list"><div v-for="(treasure,index) in character.treasure" :key="`${treasure}-${index}`"><span>{{ treasure }}</span><button type="button" class="secondary-button compact-action" @click="removeTreasure(index)">Remove</button></div></div></section>

<section class="level-up-sheet">
<details class="review-section review-collapsible level-up-section" open><summary><h2>Attributes</h2><span>Raise an Attribute Rank</span></summary><div class="review-collapsible-body"><div class="level-up-list"><div v-for="attribute in attributes" :key="attribute.id"><span><strong>{{ attribute.name }}</strong><small>Rank {{ character.attributes[attribute.id] }} · Modifier +{{ character.attributes[attribute.id]*2 }}</small></span><button class="secondary-button compact-action" @click="raiseAttribute(attribute.id)">Raise · {{ attributeCost(character.attributes[attribute.id]) }} XP</button></div></div></div></details>

<details class="review-section review-collapsible level-up-section" open><summary><h2>Skills</h2><span>Raise or learn Skills</span></summary><div class="review-collapsible-body"><div class="level-up-option-bar two"><label>Known Skill<select v-model="skillName" class="field-control"><option value="">Select Skill</option><option v-for="([name,rank]) in skills" :key="name" :value="name">{{ name }} · Rank {{ rank }}</option></select></label><button class="secondary-button" :disabled="!skillName" @click="raiseSkill">Raise Selected Skill</button><label>New Skill<select v-model="newSkill" class="field-control"><option value="">Select New Skill</option><option v-for="skill in skillDefinitions.filter(item=>!character?.skillRanks?.[item.name])" :key="skill.name" :value="skill.name">{{ skill.name }}</option></select></label><button class="secondary-button" :disabled="!newSkill" @click="addSkill">Learn · {{ newSkillCost }} XP</button></div><div class="level-up-known-list"><small v-for="([name,rank]) in skills" :key="name">{{ name }} · Rank {{ rank }}</small></div></div></details>

<details class="review-section review-collapsible level-up-section" open><summary><h2>Magic Level</h2><span>Current {{ magicLevel }} / {{ MAGIC_LEVEL_MAX }}</span></summary><div class="review-collapsible-body"><div v-if="magicLevel<MAGIC_LEVEL_MAX" class="magic-next-preview"><span>NEXT MAGIC LEVEL</span><strong>{{ magicLevel }} → {{ nextMagicLevel }}</strong><div><small>Mana Pool +1</small><small>Lore Spells {{ magicAllowance.lore }} → {{ nextMagicAllowance.lore }} <b v-if="nextMagicGain.lore">(+{{ nextMagicGain.lore }})</b></small><small>Invocations {{ magicAllowance.invocation }} → {{ nextMagicAllowance.invocation }} <b v-if="nextMagicGain.invocation">(+{{ nextMagicGain.invocation }})</b></small><small v-if="magicLevel===0">Gain Lore Attunement and its Signature Spell.</small></div></div><button class="secondary-button wide" :disabled="magicLevel>=MAGIC_LEVEL_MAX" @click="raiseMagic">{{ magicLevel>=MAGIC_LEVEL_MAX?'Magic Level Maximum':`Raise to Magic Level ${nextMagicLevel} · ${advancementCost('magic',magicLevel)} XP` }}</button><div v-if="magicLevel>0" class="level-up-known-list"><small>Lore Spells {{ knownLoreSpells.length }} / {{ magicAllowance.lore }}</small><small>Invocations {{ knownInvocationSpells.length }} / {{ magicAllowance.invocation }}</small><small>Signature {{ character.loreAttunement?'Known':'Unclaimed' }}</small></div><div class="level-up-option-stack"><template v-if="magicLevel>0&&!character.loreAttunement"><label>Lore Attunement<select v-model="newLoreAttunement" class="field-control"><option value="">Select Lore</option><option v-for="lore in attunementOptions" :key="lore" :value="lore">{{ lore }}</option></select></label><button class="secondary-button wide" :disabled="!newLoreAttunement" @click="claimLoreAttunement">Claim Lore Attunement</button></template><template v-if="loreClaimsRemaining>0"><label>Unclaimed Lore Spell ({{ loreClaimsRemaining }} remaining)<select v-model="newLoreSpell" class="field-control"><option value="">Select Lore Spell</option><option v-for="spell in loreSpellOptions" :key="spell" :value="spell">{{ spell }}</option></select></label><button class="secondary-button wide" :disabled="!newLoreSpell" @click="claimLoreSpell">Learn Lore Spell</button></template><template v-if="invocationClaimsRemaining>0"><label>Unclaimed Invocation ({{ invocationClaimsRemaining }} remaining)<select v-model="newInvocationSpell" class="field-control"><option value="">Select Invocation</option><option v-for="spell in invocationSpellOptions" :key="spell" :value="spell">{{ spell }}</option></select></label><button class="secondary-button wide" :disabled="!newInvocationSpell" @click="claimInvocationSpell">Learn Invocation</button></template></div></div></details>

<details class="review-section review-collapsible level-up-section" open><summary><h2>Talents</h2><span>{{ character.talents?.length||0 }} known</span></summary><div class="review-collapsible-body"><div class="level-up-option-bar"><label>New Talent<select v-model="newTalent" class="field-control"><option value="">Select Talent</option><option v-for="talent in talentOptions" :key="talent" :value="talent">{{ talent }}</option></select></label><button class="secondary-button" :disabled="!newTalent" @click="addTalent">Learn · {{ talentCost }} XP</button></div><div v-if="character.talents?.length" class="level-up-known-list"><small v-for="talent in character.talents" :key="talent">{{ canonicalTalentName(talent) }}</small></div></div></details>

<details class="review-section review-collapsible level-up-section" open><summary><h2>Equipment &amp; Gear</h2><span>{{ wealthLabel }}</span></summary><div class="review-collapsible-body"><div class="level-up-option-bar"><button type="button" class="secondary-button wide" @click="shopOpen=true">Open Equipment &amp; Gear Shop</button></div><div v-if="character.equipment?.length" class="owned-gear-list"><div v-for="(item,index) in character.equipment" :key="`${item.name}-${index}`" class="owned-gear-entry"><div class="owned-gear-copy"><strong>{{ item.name }}<template v-if="Number(item.quantity||1)>1"> ×{{ item.quantity }}</template></strong><small v-if="item.choice">{{ item.choice }}</small><label v-if="ownedAttachmentTargets(item).length" class="owned-gear-attachment">Attach / Apply<select class="field-control" :value="item.attachedTo||''" @change="setOwnedAttachment(index,$event)"><option value="">Not attached</option><option v-for="target in ownedAttachmentTargets(item)" :key="target" :value="target">{{ target }}</option></select></label></div><div class="owned-gear-actions"><button v-if="protectiveGearKind(item)" type="button" class="secondary-button compact-action" :class="{active:item.equipped}" :disabled="item.equipped!==true&&!canEquipProtectiveEquipment(character.equipment,index)" @click="equipProtective(index)">{{ item.equipped?'Equipped':'Equip' }}</button><button v-if="isTrinketGear(item)" type="button" class="secondary-button compact-action" :class="{active:item.equipped}" @click="toggleOwnedTrinket(index)">{{ item.equipped?'Equipped':'Equip' }}</button><button type="button" class="secondary-button compact-action" @click="sellOwnedGear(index)">Sell · {{ formatThreadpieceWp(ordinaryGearResaleWp(item)*Math.max(1,Number(item.quantity)||1)) }}</button></div></div></div></div></details>
</section>
<p v-if="message" class="creation-status-message">{{ message }}</p><div class="button-row end"><RouterLink class="secondary-button" to="/rules/read/beyond-character-creation">Read Beyond Character Creation</RouterLink><button class="primary-button" @click="finish">Done</button></div>
</template>
<section v-else-if="selectedCharacter?.locked" class="empty-state card-surface"><h2>Character Locked</h2><p>Unlock this character before using Level Up.</p><RouterLink class="primary-button" to="/characters">Back to Character Roster</RouterLink></section><section v-else-if="selectedCharacter" class="empty-state card-surface"><h2>Approval Required</h2><p>Move this completed character to Approved Characters before using Level Up.</p><RouterLink class="primary-button" to="/characters">Back to Character Roster</RouterLink></section><section v-else class="empty-state card-surface"><h2>Character Not Found</h2><p>This saved character is not available on this device.</p><RouterLink class="primary-button" to="/characters">Back to Character Roster</RouterLink></section>
<EquipmentShopModal v-if="character" :open="shopOpen" :items="gearOptions" :balance-wp="characterWealthWp(character)" :might="Number(character.attributes.might||0)" @close="shopOpen=false" @purchase="purchaseFromSharedShop" />
</main>
</template>

<style scoped>
